-- Name: enforce_stock_movement_immutability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_stock_movement_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('mill_ledger.bypass_immutability', true) = 'on' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  RAISE EXCEPTION 'Stock movements are immutable: % on stock_movement is prohibited', TG_OP;
END;
$$;


